// Charts of an xls workbook in the workbook view: an embedded chart is drawn
// in its frame from the cells its series read, a chart sheet fills the view
// with its chart, and a chart of a kind that is not drawn (a surface) stays a
// placeholder, with the note of its sheet.
//
// No screenshots: the pixels of the canvas are read with getImageData().
// Every workbook is generated by code, record by record (see
// test/xls-chart-fixtures.ts: the records were not compared with a file of
// Excel). The chart stands within columns A to D (header 72 x 22, columns 64
// wide, rows 20 high), so that a phone shows all of it. Its series is filled
// with one plain colour and its value axis runs from 0 to 100 whatever the
// cells hold, so that the height of a column is its value.
import type { Page } from '@playwright/test';
import { buildCfb } from '../test/doc-binary-fixtures';
import { clientAnchor, drawingRecords, shape } from '../test/xls-art-fixtures';
import { areaFormat, axisRec, bar, block, catSerRange, chartRecords, chartSubstream, lineFormat, tick, valueRange, type XlsChartSpec } from '../test/xls-chart-fixtures';
import { cat, externSheet, number, ptg, rec, str16, supBookSelf, u16, workbookStream } from '../test/xls-fixtures';
import { expect, test } from './helpers';

const GREEN = [0, 176, 80];
const PLACEHOLDER = [241, 243, 244];
/** The frame of the chart on the canvas, CSS pixels: A6 to the start of E19. */
const FRAME = { x: 72, y: 22 + 5 * 20, width: 4 * 64, height: 13 * 20 };

const label = (row: number, col: number, text: string): Uint8Array => rec(0x0204, u16(row), u16(col), u16(15), str16(text));
/** Names in A1:A3, the values 10, 20 and 40 in B1:B3. */
const cells = (): Uint8Array => cat(...['Tea', 'Coffee', 'Milk'].map((text, i) => label(i, 0, text)), ...[10, 20, 40].map((value, i) => number(i, 1, value)));

/** One series of columns filled green over a value axis from 0 to 100. */
const columns = (type: Uint8Array = bar(0, 100)): XlsChartSpec => ({
  series: [{ name: 'Drinks', values: ptg.area3d(0, 0, 2, 1, 1), categories: ptg.area3d(0, 0, 2, 0, 0), format: [lineFormat({ style: 5 }), areaFormat({ color: '00B050' })] }],
  axes: [block(axisRec(0), catSerRange(), tick()), block(axisRec(1), valueRange({ min: 0, max: 100, major: 20 }), tick())],
  groups: [{ type }],
});

/** A workbook with the chart on its first sheet (A6 to E19) and the same chart on a chart sheet. */
function book(type?: Uint8Array): Uint8Array {
  const spec = columns(type);
  const drawing = drawingRecords([shape({ kind: 201, ot: 5, id: 1, extra: [chartSubstream(spec)], anchor: clientAnchor([0, 0, 5, 0], [4, 0, 18, 0]) })]);
  const stream = workbookStream({
    tail: cat(supBookSelf(2), externSheet([0, 0, 0])),
    sheets: [
      { name: 'Data', records: cat(cells(), drawing) },
      { name: 'Chart1', type: 2, records: chartRecords(spec) },
    ],
  });
  return buildCfb([['Workbook', stream]]);
}

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/view.html');
  await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountView(data, options);
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', `return ${code}`)((window as any).__view), code);

interface Ink {
  /** Pixels of the colour, in pixels of the backing store. */
  count: number;
  /** Runs of pixel columns that hold the colour, left to right: how many pixels the fullest column of each holds. */
  runs: number[];
  /** Backing store pixels of the box. */
  area: number;
}

/** Looks for a colour in a box of the canvas (CSS pixels; the whole canvas without a box), after a forced redraw. */
function ink(page: Page, colour: number[], box?: { x: number; y: number; width: number; height: number }): Promise<Ink> {
  return page.evaluate(
    ([colour, box]) => {
      const view = (window as any).__view;
      view.render();
      const canvas = document.querySelector('.bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      const area = box as { x: number; y: number; width: number; height: number } | null;
      const x = area ? Math.round(area.x * dpr) : 0;
      const y = area ? Math.round(area.y * dpr) : 0;
      const width = area ? Math.round(area.width * dpr) : canvas.width;
      const height = area ? Math.round(area.height * dpr) : canvas.height;
      const data = canvas.getContext('2d')!.getImageData(x, y, width, height).data;
      const [r, g, b] = colour as number[];
      const heights: number[] = [];
      let count = 0;
      for (let px = 0; px < width; px++) {
        let column = 0;
        for (let py = 0; py < height; py++) {
          const at = (py * width + px) * 4;
          if (Math.abs(data[at] - r) <= 3 && Math.abs(data[at + 1] - g) <= 3 && Math.abs(data[at + 2] - b) <= 3) column++;
        }
        heights.push(column);
        count += column;
      }
      const runs: number[] = [];
      for (let px = 0; px < width; px++) {
        if (heights[px] === 0) continue;
        if (px > 0 && heights[px - 1] > 0 && runs.length > 0) runs[runs.length - 1] = Math.max(runs[runs.length - 1], heights[px]);
        else runs.push(heights[px]);
      }
      return { count, runs, area: width * height };
    },
    [colour, box ?? null] as [number[], typeof box | null],
  );
}

/** `a` is `factor` times `b`, give or take the pixels an edge may be off by. */
function expectRatio(a: number, b: number, factor: number): void {
  expect(Math.abs(a - b * factor), `${a} is ${factor} times ${b}`).toBeLessThanOrEqual(2 + factor * 2);
}

test.describe('charts of an xls workbook', () => {
  test('an embedded chart is drawn in its frame, from the cells its series read: no placeholder', async ({ page }) => {
    await mount(page, book());
    expect(await view(page, 'view.getDrawingState().objects')).toBe(1);
    const inside = await ink(page, GREEN, FRAME);
    expect(inside.runs.length, 'three columns in the colour of the series').toBe(3);
    // The cells hold 10, 20 and 40 on an axis from 0 to 100.
    expect(inside.runs[0]).toBeGreaterThan(8);
    expectRatio(inside.runs[1], inside.runs[0], 2);
    expectRatio(inside.runs[2], inside.runs[0], 4);
    // The frame is the chart's own, not the grey box of a placeholder; nothing of the series leaves the frame.
    const grey = await ink(page, PLACEHOLDER, FRAME);
    expect(grey.count / grey.area).toBeLessThan(0.01);
    expect((await ink(page, GREEN)).count).toBe(inside.count);
  });

  test('the tab of a chart sheet shows its chart across the view; the sheet beside it shows its cells again', async ({ page }) => {
    await mount(page, book());
    const onSheet = await ink(page, GREEN);
    await view(page, 'view.setActiveSheet(1)');
    const onChartSheet = await ink(page, GREEN);
    // The same three columns, now as large as the view lets them be.
    expect(onChartSheet.runs.length).toBe(3);
    expect(onChartSheet.count).toBeGreaterThan(onSheet.count * 2);
    expect(onChartSheet.count / onChartSheet.area).toBeGreaterThan(0.04);
    expectRatio(onChartSheet.runs[2], onChartSheet.runs[0], 4);
    await expect(page.locator('.bym-note')).toBeHidden();
    await view(page, 'view.setActiveSheet(0)');
    expect((await ink(page, GREEN)).count).toBe(onSheet.count);
  });

  test('a chart of a kind that is not drawn stays a placeholder, on its sheet and on a chart sheet', async ({ page }) => {
    // A surface chart: Surf (0x103F).
    await mount(page, book(rec(0x103f, u16(0))));
    expect(await view(page, 'view.getDrawingState().objects')).toBe(1);
    expect((await ink(page, GREEN)).count).toBe(0);
    const grey = await ink(page, PLACEHOLDER, FRAME);
    expect(grey.count / grey.area).toBeGreaterThan(0.8);
    await view(page, 'view.setActiveSheet(1)');
    expect((await ink(page, GREEN)).count).toBe(0);
    await expect(page.locator('.bym-note')).toBeVisible();
    await expect(page.locator('.bym-note')).toContainText('chart sheet');
  });
});
